commands.command:
"<USER>\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -Command '$actual = Get-Content -Raw output.json | ConvertFrom-Json
$expected = Get-Content -Raw input.json | ConvertFrom-Json
$expectedTotal = 0
foreach ($entry in $expected.values) { $expectedTotal += $entry }
$expectedHash = (Get-FileHash -LiteralPath input.json -Algorithm SHA256).Hash.ToLowerInvariant()
if ($actual.generation -cne $expected.generation) { throw '"'Generation mismatch' }
if ("'$actual.total -ne $expectedTotal) { throw '"'Total mismatch' }
if ("'$actual.input_sha256 -cne $expectedHash) { throw '"'SHA256 mismatch' }
if (("'$actual.PSObject.Properties.Name | Sort-Object) -join '"',' -cne 'generation,input_sha256,total') { throw 'Unexpected fields' }
Get-Content -Raw output.json
Write-Output 'Independent validation passed.'"
